<script setup lang="ts">
import {ref} from 'vue';
import {invoke} from '../bridge';
import type {InstallPreflight} from '../../main/install-preflight';
import {Flame,ArrowRight,Download,ShieldCheck,FolderOpen,X,LoaderCircle} from 'lucide-vue-next';
import {useDesktop} from '../useDesktop';
import {useModalFocus} from '../modalFocus';
const d=useDesktop();const {create,loading,state}=d;const advanced=ref(false),step=ref(1);
const checking=ref(false),checkError=ref(''),preflight=ref<InstallPreflight|null>(null);
async function prepare(){step.value=2;if(!d.native)return;checking.value=true;checkError.value='';preflight.value=null;try{preflight.value=await invoke('installPreflight',{port:Number(create.value.port)||0});}catch(e:any){checkError.value=e.message;}finally{checking.value=false;}}
useModalFocus('.create-dialog',()=>{d.modal.value=null;},()=>!loading.value);
</script>
<template><div class="overlay" @click.self="!loading&&(d.modal.value=null)"><section class="dialog create-dialog" role="dialog" aria-modal="true" aria-label="新建酒馆实例"><button class="dialog-close" aria-label="关闭弹窗" :disabled="loading" @click="d.modal.value=null"><X :size="19"/></button><div class="dialog-mark"><Flame :size="29"/></div><span class="eyebrow">YOUR NEXT ADVENTURE</span><h2>{{step===1?'为你的酒馆起个名字':'准备好，就点亮这间酒馆'}}</h2><p>{{step===1?'每间酒馆有独立环境和存档。第一次使用，推荐设置就足够。':'桌面会准备运行环境并检查服务状态，你可以随时在任务中心查看进度。'}}</p><ol class="compact-steps"><li :class="{active:step===1}">1 · 创建酒馆</li><li :class="{active:step===2}">2 · 准备环境</li><li>3 · 开一场冒险</li></ol><form v-if="step===1" class="form" @submit.prevent="prepare"><label>酒馆名称<input v-model="create.name" required maxlength="48" autofocus placeholder="例如：周末的余烬酒馆"/></label><label class="checkbox"><input v-model="create.lan" type="checkbox"/>允许可信局域网同伴通过浏览器入座</label><button class="text-button" type="button" :aria-expanded="advanced" @click="advanced=!advanced">{{advanced?'收起高级设置':'高级设置'}} · 端口自动选择</button><label v-if="advanced">游戏端口（留空自动选择）<input v-model.number="create.port" type="number" min="1024" max="65535" placeholder="自动选择可用端口"/></label><button class="primary full">继续 <ArrowRight :size="17"/></button></form><template v-else><div class="installation-summary"><div><Flame :size="19"/><span>酒馆</span><b>{{create.name}}</b></div><div><FolderOpen :size="19"/><span>数据位置</span><code>{{state.root}}\instances\&lt;新实例&gt;\data</code></div><div><ShieldCheck :size="19"/><span>默认主持</span><b>演示模式 · 无需模型密钥</b></div></div><div v-if="d.native" class="install-preflight" aria-live="polite"><p v-if="checking">正在检查目录、剩余空间、端口和安装来源…</p><p v-if="checkError" class="warning" role="alert">{{checkError}}</p><template v-if="preflight"><p v-for="check in preflight.checks" :key="check.id" :class="check.status==='warning'?'warning':'help-text'">{{check.status==='passed'?'✓':'待确认'}} · {{check.detail}}</p><p class="help-text">可用空间：{{preflight.availableBytes===null?'未知':(preflight.availableBytes/1024**3).toFixed(1)+' GiB'}}。Python {{preflight.pythonVersion}} 下载包：{{preflight.pythonBytes===null?'未知':(preflight.pythonBytes/1024**2).toFixed(1)+' MiB'}}；解压、环境与依赖还需额外空间，完整需求尚未确定。</p></template><button class="text-button" :disabled="checking||loading" @click="prepare">重新检查安装条件</button></div><p class="help-text">首次需要联网下载独立 Python 与锁定依赖，下载大小以实际响应为准。本体随桌面提供，不修改系统 PATH。</p><div class="dialog-actions"><button class="secondary" :disabled="loading||checking" @click="step=1">上一步</button><button class="primary" :disabled="loading||checking||!!checkError||(d.native&&!preflight)" @click="d.createInstance()"><LoaderCircle v-if="loading" class="spin" :size="17"/><Download v-else :size="17"/>{{loading?'正在创建…':'创建、安装并启动'}}</button></div></template></section></div></template>
